      "rawText": "首页 风闻 财经 国际 军事 观出行 观金融 产经 科技 城事 滚动 观察员 视频 英伟达：超级AI卡特尔的最后一块拼图 李丽梦 2026年11月，中期选举“超级蓝潮”刚刚落幕，美股AI板块便集体下挫，英伟达甚至在11月5日创下单日大跌9.3%的十年记录。 一天之后，《纽约时报》与《金融时报》老牌条线记者同步曝出所谓黄仁勋丑闻，经过周末的急速发酵，皮衣教父被迫公开认错，英伟达董事会也宣布启动独立调查。 对这一连串目不暇给的事态，外界往往把幕后推手的角色指向共和党国安鹰派或是民主党的民粹力量。 实情恰恰相反。 继上篇对英伟达控制权的梳理后，羽扇观金工作室将进一步沿着人际网络进行扩展，独家揭开民主党建制派权贵对美国AI产业的统治力。 对这些波士顿、纽约与华盛顿的蓝血贵族而言，对英伟达的围猎压根不是杀鸡儆猴敲打新贵，而是补上自己已经搭建起的超级AI卡特尔最后一块拼图。 1 Anthropic和OpenAI在前沿模型上的双寡头地位，已经近乎家喻户晓的通识，但你知道么，看似相爱相杀的两巨头，董事会和高管团队里却坐着同一批奥巴马栽培的民主党精英。 在前沿模型阵营里，Anthropic从创立之初就主",
